function ShowOverlay()
    local go = CS.UnityEngine.Resources.Load('CleanUpAction')
    local overlay = nil
    if go then
        if not UIModule.RootCanvas.transform.parent:Find("CleanUpAction") then
            overlay = KTool.Instantiate(UIModule.RootCanvas.transform.parent.gameObject, go, false)
        else
            overlay = UIModule.RootCanvas.transform.parent:Find("CleanUpAction").gameObject
        end
        local CanvasScaler      = CS.UnityEngine.UI.CanvasScaler
        local scaleComp = KTool.GetComponent(overlay.gameObject, typeof(CanvasScaler))
        if not isNull(scaleComp) then
            KTool.CalculateScreenFit(scaleComp)
        end
        overlay.name = "CleanUpAction"
    end
    return overlay
end

---RestartVmReload
---重新运行下虚拟机的逻辑
function RestartVmReload(cb)
    local overlay = nil
    if not UIModule.RootCanvas.transform.parent:Find("CleanUpAction") then
        overlay = ShowOverlay()
    else
        overlay = UIModule.RootCanvas.transform.parent:Find("CleanUpAction").gameObject
    end
    blocker:AddCondition("RestartVmReload")
    cs_coroutine.start(function()
        xpcall(function()
            local trans = UIModule.RootCanvas.transform
            local count = trans.childCount
            local t = {}
            for i = 1, count do
                local child = trans:GetChild(i - 1)
                if child and (child.name == "NetworkLoading" or child.name == "UINavigationBarRoot" or child.name == "FriendPVPPrompt") then
                    table.insert(t, child)
                end
            end
            for i, v in pairs(t) do
                if v then
                    KTool.SafeDelete(v.gameObject, true)
                end
            end
            if GameUtils then
                ----@type GuideComponent
                local guideComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)
                if guideComponent then
                    guideComponent:DestroyGuide()
                end
            end
            CS.Engine.Modules.CDTimerModule.GetInstance():Clear()
            CS.Engine.Modules.TimerModule.Instance:Stop()
            ---清除所有的倒计时
            CS.Engine.Lib.KCookie.PurgeCache()
            ---清理pool manger中的缓存
            local GOPoolManager = CS.Engine.Lib.GOPoolManager
            GOPoolManager.Instance:TearDown() --清理pool
            ---开启协程去处理卸载的逻辑
            ---清理pool manger中的缓存
            local PoolManager = CS.Engine.Lib.PoolManager
            PoolManager.Instance:TearDownAll()
            --before
            ---@type ECSWorldMgr
            local worldMgr = ECSWorldMgr:GetInstance()
            ---@type ECSWorld
            local world = worldMgr:GetWorld("GameWorld")
            local dojo = nil
            if world then
                ---@type ECSEntity
                local entity = world:GetEntity(100002)
                if entity then
                    ---@type UserComponent
                    local userComponent = entity:GetComp("UserComponent")
                    if userComponent and userComponent.userInfo then
                        dojo = clone(userComponent.userInfo)
                    end
                end
            end
            Unload()
            --- 清理配表缓存
            CS.Engine.Modules.SettingModule.ClearCache()
            Start()

            ---@type ECSWorldMgr
            local worldMgr = ECSWorldMgr:GetInstance()
            worldMgr:Initial(200)
            local ecsWorld = worldMgr:CreateWorld("GameWorld")
            ecsWorld:IsClient(true)
            local entity = ecsWorld:CreateEntity(100002, 100002)
            if entity then
                ---@type UserComponent
                local userComponent = entity:GetOrAddComp("UserComponent")
                if dojo then
                    ---重新修改值的逻辑
                    userComponent.userInfo = dojo
                end
            end

            ---刷新i18n数据
            local currentLang = CS.Engine.Lib.I18NManager.Instance.CurrentLanguage
            CS.Engine.I18N.I18NModule.SetLang(currentLang)

            ---清理资源
            ---@type Engine.Modules.Atlas.SpriteManager
            local instance = CS.Engine.Modules.Atlas.SpriteManager.Instance
            if instance then
                cs_coroutine.yield_return(instance:UnloadUnusedAssets())
            end
            local spriteAtlasMgr = CS.Engine.Modules.Atlas.SpriteAtlasManager.Instance()
            if spriteAtlasMgr then
                cs_coroutine.yield_return(spriteAtlasMgr:UnloadUnusedAssets())
            end
            if type(typeof(CS.Engine.Lib.UII18nText)) == 'userdata' then
                ---兼容老的服务器
                CS.Engine.Lib.UII18nText.ResetTextConfig()
            end

            --networkloading的loader如果在第一个，引擎存在bug时会无法卸载，提前做卸载
            --<CAT-35992>【TW】6月5日更新后下次热更会导致玩家卡死
            local LoadersPool = CS.Engine.Modules.AbstractResourceLoader.LoadersPool
            local ret ,  loderMap = LoadersPool:TryGetValue(typeof(CS.Engine.Modules.AssetBundleLoader))
            if isNotNull(loderMap) then
                local ret , loader = loderMap:TryGetValue("prefabs/networkloading.prefab.bytes")
                if isNotNull(loader) then   
                    loader:ForceUnload()
                end
            end

            cs_coroutine.yield_return(CS.Engine.Modules.ResourceModule.UnloadAssets())

            CS.Engine.Modules.AssetBundleLoader.PreLoadManifest(true)
            if spriteAtlasMgr and spriteAtlasMgr.LoadAtlasConfigData then
                spriteAtlasMgr:LoadAtlasConfigData()
            end
            ---@type GLoaderCache
            local loaderCache = GLoaderCache or import('Game.Entry.GLoaderCache')
            loaderCache.Init()
            --cs_coroutine.yield_return()
            ---重新设置图型配置
            XGraphicSetup.SetUp()
            if cb then
                cb()
            end
            if not isNull(overlay) then
                KTool.SafeDelete(overlay, true)
            end
            blocker:RemoveCondition("RestartVmReload")
        end, function()
            blocker:RemoveCondition("RestartVmReload")
            if not isNull(overlay) then
                KTool.SafeDelete(overlay, true)
            end
        end)
    end)
end
