local CriAssetManager = CS.Engine.Lib.CriAssetManager
local PathUtility = CS.Engine.Lib.PathUtility
local AssetFolder = "CriWare"
local PathSpe = '/'
local function GetManaPath(moviePath)
    local documentPath = CriAssetManager.BuildFilePath(moviePath)
    if not CS.System.IO.File.Exists(documentPath) then
        if Config.DEBUG and CS.UnityEngine.Application.isEditor then
            -- Unity开发环境使用：[cat-proj]/Product/CriwareResources/ExternalResources 作为检索目录。这样就不必记得每次 copy Sound To StreamingAssets 了
            documentPath = PathUtility.Combine(CS.Engine.Lib.CriAssetDefinition.GetSourcePath(), moviePath)
        else
            moviePath = AssetFolder .. PathSpe .. moviePath
            documentPath = PathUtility.Combine(CS.CriWare.Common.streamingAssetsPath, moviePath)
        end
    end
    return documentPath
end

---IsSmallPackage
---判断是否为小包的逻辑
local function IsSmallPackage()
    local isSmallPackage = checkNumber(AppEngine.GetConfig("Engine", "IsSmallPackage", false))
    local preVersion = PlayerPrefsUtility.GetEncryptedString(SmallPackageDownloaded, "")
    local isSmall = false
    if isSmallPackage == 1 and preVersion ~= Application.version then
        ---最新的分包的逻辑，要进行检测更新相关的逻辑
        isSmall = true
    end
    return isSmall
end

function GameStartInit:Awake()
    x_record_event('START')
    self.isSubPatch = false
    self.isSmallPackage = IsSmallPackage()
    local proGo = self.ProText.gameObject
    self.ProText = KTool.GetComponent(proGo, typeof(CS.UnityEngine.UI.Text))
    if isNull(self.ProText) then
        self.ProText = KTool.GetComponent(proGo, typeof(CS.TMPro.TextMeshProUGUI))
    end
    local imageTips = self.Root.transform.parent:Find("BgRoot/UI/Image/ImgTips")
    if imageTips then
        KTool.SetActive(imageTips.gameObject, true)
    end
    --显示版本
    ---@type Engine.Lib.AppVersion
    local version = Game.Instance.Version
    --MAJOR.MINOR.PATCH.BUILD.DESC
    local versionStr = string.format('%d.%d.%d.%d', version.Major, version.Minor, version.Patch, version.Build)
    if isSet(self, 'BigVersionTxt') then
        self.BigVersionTxt.text = Application.version
        self.LocalVersionTxt.text = versionStr
        self.RemoteVersionTxt.text = ''
    end

    --热更新写入的路径
    if isSet(self, 'UpdateBottom') then
        KTool.SetActive(self.UpdateBottom.gameObject, false)
    end
    if Config.SHOW_FPS then
        local go = CS.UnityEngine.GameObject.Find("FPSLabel_Runtime")
        if isNull(go) then
            cs_coroutine.start(function()
                ---建立fpslabel
                local loader = ResourceModule.LoadBundleAsync('Prefabs/Debug/FPSLabel.prefab', nil, true)
                while not loader.IsCompleted do
                    cs_coroutine.yield_return()
                end
                if not loader.IsSuccess or loader.IsError then
                    loader:Release(true)
                else
                    -- local go = KTool.Instantiate(CS.Game.Native.Game.UIRoot, loader.ResultObject)
                    local go = loader:Instantiate(CS.Game.Native.Game.UIRoot)
                    go.name = 'FPSLabel_Runtime'
                    KTool.SetActive(go, true)
                    loader:Release()
                end
            end)
        end
    end
    
    -- 是否是小包
    if self.isSmallPackage then
        KTool.SetActive(self.BtnRepair.gameObject, false)
        self:StartSmallPackageDownloader()
    else
        ---分包下载完的情况
        Start()
        if isTable(ECSWorldMgr) then
            ECSWorldMgr:GetInstance():Delete()
        end

        local ecsWorld = ECSWorldMgr:GetInstance():GetWorld(Constants.GameWorld)
        if not isNull(ecsWorld) then
            ECSWorldMgr:GetInstance():DestroyWorld(ecsWorld)
        end
        ECSWorldMgr:GetInstance():Initial(200)
        ecsWorld = ECSWorldMgr:GetInstance():CreateWorld(Constants.GameWorld)
        ecsWorld:IsClient(true)
        ecsWorld:CreateEntity(Constants.PlayerEntityId, Constants.PlayerEntityId)
    end
    UIEventProxy.Create(self.BtnUpdate.gameObject).onPointerClick = function()
        KTool.SetActive(self.BtnUpdate, false)
        cs_coroutine.start(function()
            self:CheckUpdater()
        end)
    end
    UIEventProxy.Create(self.CommonButton_Main_Cancel.gameObject).onPointerClick = function(eventData)
        ---确认下载的逻辑
        if not self.isSmallPackage then
            local version = self.requestVersionState_.RemoteResVersion.version
            xRecord.record('14-003', string.format('click_n_%s_1', tostring(version)))
            Application.Quit()
        else
            ---小包的取消直接进游戏
        end
    end

    -- 是否开启战斗调试面板
    if Config.SHOW_FIGHT_DEBUG then
        local go = CS.UnityEngine.GameObject.Find("SceneChanger_Runtime")
        if isNull(go) and CfUtils and CfUtils.GameObjectFindInactive then
            go = CfUtils.GameObjectFindInactive('SceneChanger_Runtime')
        end
        if isNull(go) then
            cs_coroutine.start(function()
                ---建立fpslabel
                local loader = ResourceModule.LoadBundleAsync('Prefabs/Debug/SceneChanger.prefab', nil, true)
                while not loader.IsCompleted do
                    cs_coroutine.yield_return()
                end
                if not loader.IsSuccess or loader.IsError then
                    loader:Release(true)
                else
                    -- local go = KTool.Instantiate(CS.Game.Native.Game.UIRoot, loader.ResultObject)
                    local go = loader:Instantiate(CS.Game.Native.Game.UIRoot)
                    go.name = 'SceneChanger_Runtime'
                    KTool.SetActive(go, not Config.DEBUG_QUICK_START)
                    loader:Release()
                end
            end)
        end
    end
    self.playerEnterGameHandler = Events.AddListener("PlayerDownloadThirdEvent" , Bind(self, self.CheckThirdAndUpdatePackage))
    self.startCheckUpdateHandler = Events.AddListener("PreDownloadCheckInOnSuccess", Bind(self, self.OnUserLoginSuccess))
    self.startSmallPackageHandler = Events.AddListener("StartPackageDownload", function()
        if self.isDownloadStarted then
            return
        end
        xRecord.record('14-012', "if_download")
        if DeviceID.GetNetworkType():lower() == 'wifi' then
            ---wifi的情况下
            self.isDownloadStarted = true
            ---开始下载小包的逻辑资源加更新的资源
            self:CheckDownloadSmallOrSmallThirdPackage(false)
            -- self:StartDownloadSmallPackage(false)
        else
            GameUtils.SecondConfirm(localize("当前处于移动网络，是否下载完整资源?"), function()
                self.isDownloadStarted = true
                xRecord.record('14-013', "if_download_y")
                ---开始下载小包的逻辑资源加更新的资源
                -- self:StartDownloadSmallPackage()
                self:CheckDownloadSmallOrSmallThirdPackage()
            end, function()
                xRecord.record('14-014', "if_download_n")
                self.isDownloadStarted = false
            end)
        end
    end)
end

