---StartSmallPackageDownloader
--- start to download small package logical
---
function GameStartInit:StartSmallPackageDownloader()
    self.Slider.value = 0 ---重置下进度条
    Game.Instance:LoadVersion(true)
    ---刷新一次版本号
    self.LocalVersionTxt.text = Game.Instance.Version:ToStandardVersionString()
    local vendorPath = PathUtility.Combine(ResourceModule.AppDataPath, ResourceModule.ProductRelPath)
    --更新写入的路径
    if not Exists(vendorPath) then
        Directory.CreateDirectory(vendorPath)
    end
    ---资源版本号信息是否存在
    local versionFile = PathUtility.Combine(vendorPath, resource_version_filename)
    if not File.Exists(versionFile) then
        File.WriteAllText(versionFile, Game.Instance.Version:ToString())
    end
    ---大版本号的写入的逻辑
    local bigVersionFile = PathUtility.Combine(vendorPath, resource_big_version_filename)
    if not File.Exists(bigVersionFile) then
        File.WriteAllText(bigVersionFile, Application.version)
    end

end

