function GameStartInit:OnUserLoginSuccess()
    if KCookie.Get("GAME_BACK_TO_LOGIN") then
        ---@type Engine.Lib.AppVersion
        local version = Game.Instance.Version
        ---游戏中回来时，显示远程版本
        self.RemoteVersionTxt.text = version:ToStandardVersionString()
    else
        print('---->>> login success2', Application.version)
        ---刚启动的逻辑，点了游戏时
        if self.isSmallPackage then
            ---先请求小包的下载的逻辑
