function GameStartInit:HandleUserUpdate()
    self.RemoteVersionTxt.text = tostring(self.userUpdateInfo.version)
    KCookie.Set("IS_MAINTAIN_SERVER", checkString(self.userUpdateInfo.isMaintain))
    if checkNumber(self.userUpdateInfo.isForceUpdate) == 1 then
        xTry(function()
            ---@type Engine.Modules.AbstractResourceLoader
            local loader = ResourceModule.LoadBundleSync("Prefabs/Common/SecondConfirmPopUp.prefab", nil, true)
            if loader.IsSuccess then
                local parent = UIModule.RootCanvas.transform.parent
                --//将检测更新界面加入到初始页面中去
                local go = loader:Instantiate(parent.transform, false)
                loader:Release()
                go.name = "SecondConfirmPopUp"
                if not KTool.IsNull(go) and not KTool.IsNull(parent) then
                    local t = go:GetComponent(typeof(RectTransform))
                    t.anchorMin = Vector2.zero
                    t.anchorMax = Vector2.one
                    t.offsetMin = Vector2.zero
                    t.offsetMax = Vector2.zero
                    t.localPosition = Vector3.zero
                    t.localRotation = Quaternion.identity
                    t.localScale = Vector3.one
                    go.layer = parent.gameObject.layer
                    ---获取lua脚本然后执行方法
                    local uiSecondConfirm = GetLuaBehaviour(go, "Game.Behaviours.UISecondConfirm")
                    if not KTool.IsNull(uiSecondConfirm) then
                        uiSecondConfirm.Env:ShowHUD(localize('您的当前版本过低，请前往下载最新版本'), '', function()
                            CfUtils.OpenURL(self.userUpdateInfo.forceUpdateUrl)
                            --xRecord.record('14-002', string.format('click_y_%s_2', updateDojo.version))
                        end, function()
                            --xRecord.record('14-003', string.format('click_n_%s_2', updateDojo.version))
                            CS.UnityEngine.Application.Quit()
                        end)
                    end
                end
            else
                loader:Release(true)
            end
        end, function()
            ---如果因各种更新异常直接跳转
            CfUtils.OpenURL(self.userUpdateInfo.forceUpdateUrl)
        end)
        return
    elseif checkNumber(self.userUpdateInfo.isReview) > 0 then
        ---审核服务器,更改服务器
        HttpModule.ServerHost = checkString(self.userUpdateInfo.reviewUrl)
        HttpModule.Instance:ParseDomain()
        local staticType = typeof(HttpModule)
        local BindingFlags = CS.System.Reflection.BindingFlags
        local propertyInfo = isNotNull(staticType:GetProperty("IsEnableHost", BindingFlags.Static | BindingFlags.Public)) 
        if propertyInfo then
            HttpModule.IsEnableHost = false
        end
        
        IS_REVIEW = true
        IS_REVIEW_INT = checkNumber(self.userUpdateInfo.isReview)
    end
    ----Start to promote download logical
    if DeviceID.GetNetworkType():lower() == 'wifi' or checkNumber(self.userUpdateInfo.isDownloadPromote) == 0 then
        --GameUtils.SecondConfirm(localize("当前处理移动网络，是否下载完整资源?"), function()
        self.isDownloadStarted = true
        ---开始下载小包的逻辑资源加更新的资源
        -- self:StartDownloadSmallPackage(true)
        self:CheckDownloadSmallOrSmallThirdPackage(true)
        --end, function()
        --    self.isDownloadStarted = false
        --    self:OpenLoadingPanel()
        --end)
    else
        --promote
        xRecord.record('14-012', "if_download")
        GameUtils.SecondConfirm(localize("当前处于移动网络，是否下载完整资源?"), function()
            self.isDownloadStarted = true
            xRecord.record('14-013', "if_download_y")
            ---开始下载小包的逻辑资源加更新的资源
            -- self:StartDownloadSmallPackage(true)
            self:CheckDownloadSmallOrSmallThirdPackage(true)
        end, function()
            xRecord.record('14-014', "if_download_n")
            self.isDownloadStarted = false
            self:OpenLoadingPanel()
        end)
    end
end

---OpenLoadingPanel
---显示loading页面
function GameStartInit:OpenLoadingPanel(isDownload)
    blocker:AddCondition("LOADING_PAN")
    xTry(function()
        local parent = UIModule.RootCanvas.gameObject
        local go = GameUtils.LoadBundleSyncById(Constants.UIModulePrefabsIds.LoginLoadingPanel, parent, false, false)
        GameUtils.InitNodeDefaultParams(go, parent)
        if not KTool.IsNull(go) and not KTool.IsNull(parent) then
            go.name = "LoginLoadingPanel"
            ---@type Engine.Modules.LuaBehaviour
            local mono = GetLuaBehaviour(go, "Game.Behaviours.LoginLoadingPanel")
            if not KTool.IsNull(mono) then
                ---@type LoginLoadingPanel
                local loadingUI = mono.Env
                loadingUI:SetArg()
                KTool.SetActive(self.controller.gameObject, false)
                cs_coroutine.yield_return(cs_coroutine.start(function()
                    coroutine.yield(UIModule.CloseDialogById(Constants.UITypeIds.PassportDialog))
                    coroutine.yield(UIModule.CloseDialogById(Constants.UITypeIds.SelectServerDialog, true))
                    ---加载主界面场景如果是第一次进入的时候同步加载
                    local sceneManagement = SceneManagement:GetInstance()
                    local IdolLive3D_Loader = import('Game.IdolLive3D.IdolLive3D_Loader')
                    IdolLive3D_Loader.AppendedScene()
                    while not sceneManagement:IsSceneLoaded(Constants.IdSceneSetting54) do
                        self.displayProgress = self.displayProgress + 15
                        if loadingUI then
                            loadingUI:__Progress(self.displayProgress * 0.01)
                        end
                        coroutine.yield(Yielders.EndOfFrame)
                    end
                    KTool.GetOrAddComponent(URPCameraController.mainCamera.gameObject, typeof(CinemachineBrain))
                    local toProgress = 100
                    if self.displayProgress < toProgress then
                        while self.displayProgress < toProgress do
                            self.displayProgress = self.displayProgress + 2
                            if self.displayProgress >= toProgress then
                                break
                            end
                            if loadingUI then
                                loadingUI:__Progress(self.displayProgress * 0.01)
                            end
                            coroutine.yield(Yielders.EndOfFrame)
                        end
                    end
                    coroutine.yield(UINavigationBarRoot.Instance:Show()) --//显示通用返回条的逻辑
                    ---可能是设置中退出再进的情况，需要再显示一次
                    UINavigationBarRoot.Instance:SetActive(true)
                    UINavigationBarRoot.Instance:SetInfoTipButtonState(false)--标题也要设置为不显示
                    CfUtils.SetTopCommonActive(false, false)
                    ---@type UserComponent
                    local userComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.UserComponent)
                    local storeKey = Constants.PlayerPrefsType.PreDownloadStoryOpening
                    if userComponent then
                        local userId = userComponent.userInfo.userId
                        storeKey = storeKey .. tostring(userId)
                    end
                    local isPlayedStory = CfUtils.GetLocalData(storeKey, '') == '1'
                    if IS_REVIEW then
                        coroutine.yield(IdolLive3D_Loader.TryOpenSceneFromSmlPackage(cardSkinId, true))
                        -- 深度角色开启: 近景特写+相机冻结:
                        ---@type IdolLive3D_States
                        local IdolLive3D_States = import('Game.IdolLive3D.IdolLive3D_States')
                        Events.Broadcast(IdolLive3D_States.EventSmlPackageInitFreeze, nil)
                    else
                        coroutine.yield(IdolLive3D_Loader.TryOpenSceneFromSmlPackage(cardSkinId, not isPlayedStory))
                        if not isPlayedStory then
                            -- 深度角色开启: 近景特写+相机冻结:
                            ---@type IdolLive3D_States
                            local IdolLive3D_States = import('Game.IdolLive3D.IdolLive3D_States')
                            Events.Broadcast(IdolLive3D_States.EventSmlPackageInitFreeze, nil)
                        end
                    end
                    loadingUI:Close()
                    loadingUI = nil
                    -- 初始化下载进度界面
                    coroutine.yield(UIModule.OpenDialog({ id = Constants.UITypeIds.PreDownloadLoadHintDialog, parameters = { isDownload = isDownload } }))
                    coroutine.yield(UIModule.OpenDialog({ id = Constants.UITypeIds.PreDownloadEntryMainDialog }))
                end))
            end
        end
        blocker:RemoveCondition("LOADING_PAN")
    end, function()
        blocker:RemoveCondition("LOADING_PAN")
    end)
end
-- 检测下载三段包走哪一种逻辑
function GameStartInit:CheckDownloadSmallOrSmallThirdPackage(isLoading)
    local isSupportPackage = ThirdDownloadManager:IsSupportThirdPackage()
    if not isSupportPackage then
        self:StartDownloadSmallPackage(isLoading)
    else 
        self:StartDownloadSmallThirdPackage(isLoading)
    end
end
-- 开始下载走下载二段包逻辑
function GameStartInit:StartDownloadSmallThirdPackage(isLoading)
    cs_coroutine.start(function()
        xTry(function()
            if isLoading then
                ---开始loading的逻辑进入游戏
                cs_coroutine.yield_return(self:OpenLoadingPanel(true))
            end
            
            
            local isDelete = true
            ---@type UserComponent
            local userComponent =  GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
            local lastLoginServerId = checkInt(userComponent.userInfo.lastLoginServerId) 
            
            --[[
                way 为1 表示下载量 = 二段包 + 更新
                way 为2 表示下载量 = 三段包 + 二段包 + 更新 
            ]] 
            local way = 1
            if lastLoginServerId > 0 then
                ---@type UserDojo
                local userDojo = userComponent:GetServerById(lastLoginServerId)
                if isNotNull(userDojo)  then
                    if not (checkInt(userDojo.chapterId) < 102 and ThirdDownloadManager:IsDuoLe()) then
                        way = 2        
                    end
                end
            end
            local downloadStruct = nil
            if way == 1 then
                downloadStruct = ThirdDownloadManager:GetDownloadSecondAndUpdatePackage(self.downloadBeforeInfo , self.userUpdateInfo)
            else     
                downloadStruct = ThirdDownloadManager:GetDownloadThirdAndSecondAndUpdatePackage(self.downloadBeforeInfo , self.userUpdateInfo)
            end
            self.totalSize = downloadStruct.totalSize
            local download = DownloadState(nil, ResourceModule.AppDataPath, "Download")
            download.PatchMd5S = downloadStruct.patchDojos
            local dojo = PatchDojo()
            download.IsAutoState = true ---非自动状态有一处提示
            download.UseRetry = false ---使用重试机制    
            isDelete = true
            download.RemoteVersion = downloadStruct.RemoteVersion
            ----开始下载
            Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Starting })
            print("---->>> start downloading----->>")
            local progressMap = {}
            local downloadMemberInfo = download:GetType()
            local property = downloadMemberInfo:GetProperty("PatchMd5S")
            self.needMemorySize = 0
            if KTool.UNITY_ANDROID() then
                local SystemIOPath = CS.System.IO.Path
                local apkFilePath = CS.Engine.Modules.ResourceModule.AppDataPath
                local downloadPath = SystemIOPath.Combine(apkFilePath , "Download")
                local Directory = CS.System.IO.Directory
                local File = CS.System.IO.File
                local property = typeof(CS.Engine.Lib.AndroidPlugin):GetProperty("AvailableInternalMemorySize")
                if isNotNull(property) then
                    self.MemorySize = CS.Engine.Lib.AndroidPlugin.AvailableInternalMemorySize
                    local addSize = ADD_SPACE_SIZE
                    self.needMemorySize = (self.totalSize + ADD_SPACE_SIZE) - self.MemorySize
                    local AppEngine = CS.Engine.Lib.AppEngine
                    local version = AppEngine.GetAppBundleVersion()
                    local channelId = checkInt(version.ChannelId) 
                    if (channelId >= 6007 and channelId <= 6011) or channelId == 6013 then
                        if self.needMemorySize > 0 then
                            UIModule.OpenDialog({ id = Constants.UITypeIds.PredownloadMemoryTipsPopup, parameters = {
                                DownloadedSize = 0 , 
                                TotalSize = self.totalSize , 
                                needMemorySize = self.needMemorySize , 
                                callback = function()
                                    self:StartDownloadSmallThirdPackage(false)
                                end
                            }})
                            download:RemoveListeners()
                            return     
                        end
                    end
                end
            elseif  KTool.UNITY_IOS() then
                local DeviceID = CS.Engine.Http.DeviceID
                local isDownload = PlayerPrefsUtility.GetEncryptedString("IOS_DOWNLOAD_" ..Application.version , "0" )
                if checkInt(isDownload) ~= 1 then     
                    if DeviceID.GetFreeDiskSpaceInBytes > 0 then
                        self.MemorySize = DeviceID.GetFreeDiskSpaceInBytes
                        local addSize = ADD_SPACE_SIZE
                        self.needMemorySize = (self.totalSize + ADD_SPACE_SIZE) - self.MemorySize
                    end
                    if self.needMemorySize > 0 then
                        UIModule.OpenDialog({ id = Constants.UITypeIds.PredownloadMemoryTipsPopup, parameters = {
                             DownloadedSize = 0 , 
                             TotalSize = self.totalSize , 
                             needMemorySize = self.needMemorySize , 
                             callback = function()
                                self:StartDownloadSmallThirdPackage(false)
                             end
                        }})
                        download:RemoveListeners()
                        return     
                    end
                end
            end
            if KTool.UNITY_IOS() then
                PlayerPrefsUtility.SetEncryptedString( "IOS_DOWNLOAD_" ..  Application.version  , "1") 
                PlayerPrefsUtility.Save()   
            end
            if self.needMemorySize > 0 then
                local downloadSize = 0
                if self.MemorySize > self.totalZipSize then
                    downloadSize =  self.totalZipSize - NO_SPACE_DISTANCE_SIZE 
                else 
                    downloadSize =  self.MemorySize - NO_SPACE_DISTANCE_SIZE 
                end 
                local isPop = false
                download.ProgressCallback = function(DownloadedSize, TotalSize, speed)
                    local size = DownloadedSize
                    local Progress = size / TotalSize
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Progressing, downloadSize = size, totalSize = TotalSize, progress = Progress, speed = speed })
                    local proInt = math.floor(Progress * 100)
                    local distance = 20
                    if proInt < 20 then
                        distance = 5
                        if proInt < 5 then
                            distance = 1
                        end
                    end
                    local multiple = math.floor(proInt / distance)
                    local uploadPoint = multiple * distance
                    if not progressMap[tostring(uploadPoint)] then
                        progressMap[tostring(uploadPoint)] = uploadPoint
                        xRecord.record('14-005', string.format('download_progress_small_%s%%',uploadPoint))
                    end
                    if not isPop then
                        if DownloadedSize > downloadSize then
                            local MemorySize = CS.Engine.Lib.AndroidPlugin.AvailableInternalMemorySize
                            -- 重新计算将
                            local needMemorySize = (self.totalSize + ADD_SPACE_SIZE) - MemorySize - DownloadedSize       
                            if needMemorySize > 0 then
                                isPop = true                   
                                UIModule.OpenDialog({ id = Constants.UITypeIds.PredownloadMemoryTipsPopup, parameters = { DownloadedSize = DownloadedSize , TotalSize = self.totalSize , needMemorySize = self.needMemorySize} })        
                            end  
                        end  
                    end                    
                end
            else 
                download.ProgressCallback = function(DownloadedSize, TotalSize, speed)
                    local size = DownloadedSize
                    local Progress = size / TotalSize
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Progressing, downloadSize = size, totalSize = TotalSize, progress = Progress, speed = speed })
                    local proInt = math.floor(Progress * 100)
                    local distance = 20
                    if proInt < 20 then
                        distance = 5
                        if proInt < 5 then
                            distance = 1
                        end
                    end
                    local multiple = math.floor(proInt / distance)
                    local uploadPoint = multiple * distance
                    if not progressMap[tostring(uploadPoint)] then
                        progressMap[tostring(uploadPoint)] = uploadPoint
                        xRecord.record('14-005', string.format('download_progress_small_%s%%', uploadPoint))
                    end
                end
            end
            local downloadMemberInfo = download:GetType()
            local property = downloadMemberInfo:GetProperty("OnCheckPercentCallback")
            if isNotNull(property) then
                local verifyProgress = 0
                download.OnCheckPercentCallback = function(percent)
                    local proInt = math.floor(percent)
                    if proInt >= verifyProgress then
                        local currentProgress = verifyProgress
                        while proInt >= verifyProgress do
                            currentProgress = verifyProgress
                            verifyProgress = verifyProgress + 20
                        end
                        xRecord.record('14-022', string.format('verify_progress_%s%%', currentProgress))
                    end
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.ResourceNewCheck, progress = percent })
                end
            end
            property = downloadMemberInfo:GetProperty("OnLastMd5CheckCallback")
            if isNotNull(property) then
                download.OnLastMd5CheckCallback = function()
                    xRecord.record('14-022', string.format('verify_progress_%s%%', 75))
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.ResourceCheck })
                end
            end
            property = downloadMemberInfo:GetProperty("OnLastMargeFileCallback")
            if isNotNull(property) then
                download.OnLastMargeFileCallback = function()
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.ResourceMarge })
                end
            end
            property = downloadMemberInfo:GetProperty("OnFailCallback")
            if isNotNull(property) then
                download.OnFailCallback = function(error)
                    if error == Constants.DownloadErrorType.INSUFFICIENT_DISK_SPACE_ERROR then
                        -- GameUtils.SecondConfirm(localize("空间不足,请清理空间") ,function ()
                        --     -- CS.UnityEngine.Application.Quit()
                        -- end,function ()
                        --     -- CS.UnityEngine.Application.Quit()
                        -- end)
                        -- GameUtils.Toast(localize("空间不足,请清理空间"), 5)
                        -- GameUtils.Toast(localize("空间不足"))
                    elseif error == Constants.DownloadErrorType.UNKNOWN then
                        if not IS_REVIEW then
                            GameUtils.Toast(localize("未知错误"))    
                        end
                    elseif error == Constants.DownloadErrorType.FILE_MERGE_ERROR then
                        if not IS_REVIEW then
                            GameUtils.Toast(localize("文件错误"))
                        end
                    elseif error == Constants.DownloadErrorType.FILE_CHECK_ERROR then
                        if not IS_REVIEW then
                            GameUtils.Toast(localize("文件检测错误"))    
                        end
                    elseif error == Constants.DownloadErrorType.NETWORK_ERROR then
                        if not IS_REVIEW then
                            GameUtils.Toast(localize("网络错误"))    
                        end
                    elseif error == Constants.DownloadErrorType.BLOCK_ERROR then
                        if not IS_REVIEW then
                            GameUtils.Toast(localize("下载错误，修正中"))    
                        end
                    end
                    xRecord.record('14-010', tostring(error))
                end
            end
            
            property = downloadMemberInfo:GetProperty("OnFailStringCallback")
            if isNotNull(property) then
                download.OnFailStringCallback = function(data)
                    local downloadInfo = table.deserialize(data)
                    if isNotNull(downloadInfo.value) then
                        local value = checkInt(downloadInfo.value)
                        if value == Constants.DownloadErrorType.INSUFFICIENT_DISK_SPACE_ERROR then
                            GameUtils.Toast(localize("空间不足,请清理空间"), 5)
                            Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.DownloadSpaceNotEnough, downloadInfo = downloadInfo})
                        end
                    end 
                end
            end

            download:SetFinishCallback(function(state)
                xRecord.record('14-006', 'download_progress_small_completed')
                ---@type Engine.Lib.Updater.DownloadState
                local mState = state
                if mState.IsError then
                    xRecord.record('14-010', checkString(mState.Error.Message))
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Error, error = tostring(mState.Error.Message) })
                else
                    ----正常的下载完成
                    if not download.IsFinished then
                        download:Finish()
                    end
                    download.ProgressCallback = nil
                    download:SetFinishCallback(nil)
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.DownloadDone, progress = 100 })
                end
                xRecord.af_internal("download_end" , {version = CS.UnityEngine.Application.version})
            end)
            local vendorPath = PathUtility.Combine(ResourceModule.AppDataPath, ResourceModule.ProductRelPath)
            local decompressState = DecompressState(vendorPath, download)
            local decomProgress = 0
            decompressState.OnDecompressProgressAction = function()
                local proInt = decompressState.Progress * 100
                if proInt >= decomProgress then
                    local currentProgress = decomProgress
                    while proInt >= decomProgress do
                        currentProgress = decomProgress
                        decomProgress = decomProgress + 20
                    end
                    xRecord.record('14-007', string.format('decom_progress_%s%%', currentProgress))
                end
                ---解压文件显示
                Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Decompressing, progress = decompressState.Progress })
            end
            if KTool.UNITY_IOS() then
                decompressState.IsDeleteZip = download.PatchMd5S.Length > 1
            else    
                decompressState.IsDeleteZip = isDelete
            end
            decompressState:SetFinishCallback(function()
                if decompressState.IsError then
                    xRecord.record('14-010', checkString(decompressState.Error.Message))
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Error, error = decompressState.Error.Message })
                    ----解压出错的情况下，清理下下载目录
                    local downloadPath = PathUtility.Combine(ResourceModule.AppDataPath, "Download")
                    if Exists(downloadPath) then
                        ---更新写入的路径
                        PathUtility.Clean(downloadPath)
                    end
                    if not Exists(downloadPath) then
                        Directory.CreateDirectory(downloadPath)
                    end
                else
                    xRecord.record('14-008', 'decom_finish')
                end
            end)

            local isUseMd5 = true
            if self.downloadBeforeInfo.xxh64 and not string.isEmpty(self.downloadBeforeInfo.xxh64) then
                isUseMd5 = false
            end
            local verifyPackageState = VerifyPackageState(download, isUseMd5)
            ---@type Engine.Lib.Updater.Updater
            local updater = Updater({ download, verifyPackageState, decompressState })
            updater.FinishCallback = function(update)
                ---更新完成进入游戏
                if updater.IsError then
                    xRecord.record('14-010', tostring(updater.Error.Message))
                    ---更新出现错误了
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Error, error = updater.Error.Message })
                else
                    ---设置记录
                    PlayerPrefsUtility.SetEncryptedString(SmallPackageDownloaded, CS.UnityEngine.Application.version)
                    PlayerPrefsUtility.SetEncryptedString("IS_NEW_SMALL_PACKAGE", "1")
                    if way == 2 then
                        ThirdDownloadManager:StartDownloadThirdPackageVersion(ThirdPackageDownloaded ,CS.UnityEngine.Application.version)
                    end
                    PlayerPrefsUtility.Save() --修正分包下载在pc上的有些模拟器，前一个包安装完再立即覆盖新的包，然后写入的preVersion信息为旧的情况
                    local downloadPath = PathUtility.Combine(ResourceModule.AppDataPath, "Download")
                    if Exists(downloadPath) then
                        ---更新写入的路径
                        PathUtility.Clean(downloadPath)
                    end
                    if not Exists(downloadPath) then
                        Directory.CreateDirectory(downloadPath)
                    end
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Finish })
                end
            end
            xRecord.af_internal("download_start" , {version = CS.UnityEngine.Application.version})
            ---开启线程来检测状态
            CS.Engine.Lib.AppEngine._Instance:StartCoroutine(updater:StartEnumerator())
            while not updater.IsDone do
                cs_coroutine.yield_return(Yielders.EndOfFrame)
            end
            download:RemoveListeners()
        end)
    end)
end

---StartDownloadSmallPackage
---开始下载小包
---@param isLoading boolean 是加载界面
function GameStartInit:StartDownloadSmallPackage(isLoading)
    cs_coroutine.start(function()
        xTry(function()
            if isLoading then
                ---开始loading的逻辑进入游戏
                cs_coroutine.yield_return(self:OpenLoadingPanel(true))
            end
            ---@type Engine.Lib.Updater.DownloadState
            local download = DownloadState(nil, ResourceModule.AppDataPath, "Download")
            local downloadMemberInfo = download:GetType()
            local property = downloadMemberInfo:GetProperty("PatchMd5S")
            local split = self.downloadBeforeInfo.split
            local isDelete = true
            self.totalSize = 0 
            if (KTool.UNITY_ANDROID() or KTool.UNITY_IOS()) and isNotNull(split) and table.count(split) > 0 and isNotNull(property) then
                local count = table.count(split)
                if self.userUpdateInfo then
                    ---有更新并且存在patches,存在热更新版本的情况下
                    local hasUpdate, _ = self:GetUpdatePatches()
                    if hasUpdate then
                        count = count + 1
                        local json = checkTable(self.userUpdateInfo)
                        local remoteV = AppVersion(json.version)
                        download.RemoteVersion = remoteV
                    end
                end
                local spt = import('Frame.support')
                local patchDojos = spt.new_array(typeof(PatchDojo), count)
                for i = 1, table.count(split) do
                    local dojo = PatchDojo()
                    dojo.IsUpdate = false
                    local split = self.downloadBeforeInfo.split
                    local downloadInfo = split[i]
                    dojo.url = downloadInfo.url
                    if downloadInfo.xxh64 and not string.isEmpty(downloadInfo.xxh64) then
                        dojo.md5 = downloadInfo.xxh64
                    else
                        dojo.md5 = downloadInfo.md5
                    end
                    dojo.size = checkNumber(downloadInfo.size)
                    dojo.DecompressSize = checkNumber(downloadInfo.decompressSize)
                    patchDojos[i - 1] = dojo
                    self.totalSize = dojo.DecompressSize + self.totalSize
                    self.totalZipSize = checkNumber(dojo.size) + self.totalZipSize
                end
                if self.userUpdateInfo then
                    ---有更新并且存在patches,存在热更新版本的情况下
                    local hasUpdate, patchDojo = self:GetUpdatePatches()
                    if hasUpdate then
                        local dojo = PatchDojo()
                        dojo.IsUpdate = true
                        dojo.url = patchDojo.url
                        dojo.md5 = patchDojo.md5
                        dojo.ZipName = patchDojo.ZipName
                        dojo.size = checkNumber(patchDojo.size)
                        if isNotNull(dojo.DecompressSize)  then
                            self.totalSize = dojo.DecompressSize + self.totalSize
                        else 
                            self.totalSize = dojo.size + self.totalSize
                        end
                        self.totalZipSize = checkNumber(dojo.size) + self.totalSize
                        patchDojos[count - 1] = dojo
                    end
                end
                download.PatchMd5S = patchDojos
                local dojo = PatchDojo()
                dojo.IsUpdate = false
                dojo.url = self.downloadBeforeInfo.url
                if self.downloadBeforeInfo.xxh64 and not string.isEmpty(self.downloadBeforeInfo.xxh64) then
                    dojo.md5 = self.downloadBeforeInfo.xxh64
                else
                    dojo.md5 = self.downloadBeforeInfo.md5
                end
                download.PatchMd5 = dojo

                download.IsAutoState = true ---非自动状态有一处提示
                download.UseRetry = false ---使用重试机制    
                isDelete = true
            else
                local count = 1
                if self.userUpdateInfo then
                    ---有更新并且存在patches,存在热更新版本的情况下
                    local hasUpdate, _ = self:GetUpdatePatches()
                    if hasUpdate then
                        count = count + 1
                        local json = checkTable(self.userUpdateInfo)
                        local remoteV = AppVersion(json.version)
                        download.RemoteVersion = remoteV
                    end
                end
                local spt = import('Frame.support')
                local patchDojos = spt.new_array(typeof(PatchDojo), count)
                local dojo = PatchDojo()
                dojo.IsUpdate = false
                dojo.url = self.downloadBeforeInfo.url
                if self.downloadBeforeInfo.xxh64 and not string.isEmpty(self.downloadBeforeInfo.xxh64) then
                    dojo.md5 = self.downloadBeforeInfo.xxh64
                else
                    dojo.md5 = self.downloadBeforeInfo.md5
                end
                dojo.size = checkNumber(self.downloadBeforeInfo.size)
                if isNotNull(dojo.DecompressSize)  then
                    self.totalSize = dojo.DecompressSize + self.totalSize
                else 
                    self.totalSize = dojo.size + self.totalSize
                end
                local index = 0
                patchDojos[index] = dojo
                if self.userUpdateInfo then
                    ---有更新并且存在patches,存在热更新版本的情况下
                    local hasUpdate, patchDojo = self:GetUpdatePatches()
                    if hasUpdate then
                        index = 1
                        dojo = PatchDojo()
                        dojo.IsUpdate = true
                        dojo.url = patchDojo.url
                        dojo.md5 = patchDojo.md5
                        dojo.ZipName = patchDojo.ZipName
                        dojo.size = checkNumber(patchDojo.size)
                        patchDojos[index] = dojo
                        if isNotNull(dojo.DecompressSize)  then
                            self.totalSize = dojo.DecompressSize + self.totalSize
                        else 
                            self.totalSize = dojo.size + self.totalSize
                        end
                    end
                end
                download.PatchMd5S = patchDojos
                isDelete = false
            end
            ----开始下载
            Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Starting })
            print("---->>> start downloading----->>")
            local progressMap = {}
           
            if KTool.UNITY_ANDROID() and isNotNull(split) and table.count(split) > 0 and isNotNull(property) then
                local SystemIOPath = CS.System.IO.Path
                local apkFilePath = CS.Engine.Modules.ResourceModule.AppDataPath
                local downloadPath = SystemIOPath.Combine(apkFilePath , "Download")
                local Directory = CS.System.IO.Directory
                local File = CS.System.IO.File
                local isExist = false
                if Directory.Exists(downloadPath) then
                    local split = self.downloadBeforeInfo.split
                    for i = 1 ,  #split do
                        local zipName =  KTool.GetFileNameFromURL(split[i].url) 
                        local zipPath =  SystemIOPath.Combine(downloadPath , zipName)
                        isExist =  File.Exists(zipPath)
                        if isExist then
                            break
                        end
                    end
                    if self.userUpdateInfo then
                        ---有更新并且存在patches,存在热更新版本的情况下
                        local hasUpdate, patchDojo = self:GetUpdatePatches()
                        if hasUpdate then
                            local zipPath =  SystemIOPath.Combine(downloadPath , patchDojo.ZipName)
                            isExist =  File.Exists(zipPath) 
                        end
                    end
                    if not isExist then
                        local property = typeof(CS.Engine.Lib.AndroidPlugin):GetProperty("AvailableInternalMemorySize")
                        if isNotNull(property) then
                            self.MemorySize = CS.Engine.Lib.AndroidPlugin.AvailableInternalMemorySize
                            local addSize =  ADD_SPACE_SIZE
                            self.needMemorySize = (self.totalSize + addSize) - self.MemorySize
                        end
                    end
                else 
                    local property = typeof(CS.Engine.Lib.AndroidPlugin):GetProperty("AvailableInternalMemorySize")
                    if isNotNull(property) then
                        self.MemorySize = CS.Engine.Lib.AndroidPlugin.AvailableInternalMemorySize
                        local addSize = ADD_SPACE_SIZE
                        self.needMemorySize = (self.totalSize + ADD_SPACE_SIZE) - self.MemorySize
                    end
                end
            elseif KTool.UNITY_IOS() then
                local isDownload = PlayerPrefsUtility.GetEncryptedString("IOS_DOWNLOAD_" ..Application.version , "0")
                if checkInt(isDownload) ~= 1 then
                    local DeviceID = CS.Engine.Http.DeviceID
                    if DeviceID.GetFreeDiskSpaceInBytes > 0 then
                        self.MemorySize = DeviceID.GetFreeDiskSpaceInBytes
                        local addSize = ADD_SPACE_SIZE
                        self.needMemorySize = (self.totalSize + ADD_SPACE_SIZE) - self.MemorySize
                    end
                    if self.needMemorySize > 0 then
                        UIModule.OpenDialog({ id = Constants.UITypeIds.PredownloadMemoryTipsPopup, parameters = {
                            DownloadedSize = 0 , 
                            TotalSize = self.totalSize , 
                            needMemorySize = self.needMemorySize , 
                            callback = function()
                                self:StartDownloadSmallPackage(false)
                            end
                        }})
                        download:RemoveListeners()
                        return     
                    end
                end
            end
            if KTool.UNITY_IOS() then
                PlayerPrefsUtility.SetEncryptedString( "IOS_DOWNLOAD_" ..  Application.version  , "1") 
                PlayerPrefsUtility.Save()   
            end

            if self.needMemorySize > 0 then
                local downloadSize = 0
                if self.MemorySize > self.totalZipSize then
                    downloadSize =  self.totalZipSize - NO_SPACE_DISTANCE_SIZE 
                else 
                    downloadSize =  self.MemorySize - NO_SPACE_DISTANCE_SIZE 
                end 
                local isPop = false
                download.ProgressCallback = function(DownloadedSize, TotalSize, speed)
                    local size = DownloadedSize
                    local Progress = size / TotalSize
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Progressing, downloadSize = size, totalSize = TotalSize, progress = Progress, speed = speed })
                    local proInt = math.floor(Progress * 100)
                    local distance = 20
                    if proInt < 20 then
                        distance = 5
                        if proInt < 5 then
                            distance = 1
                        end
                    end
                    local multiple = math.floor(proInt / distance)
                    local uploadPoint = multiple * distance
                    if not progressMap[tostring(uploadPoint)] then
                        progressMap[tostring(uploadPoint)] = uploadPoint
                        xRecord.record('14-005', string.format('download_progress_small_%s%%',uploadPoint))
                    end
                    if not isPop then
                        if DownloadedSize > downloadSize then
                            local MemorySize = CS.Engine.Lib.AndroidPlugin.AvailableInternalMemorySize
                            -- 重新计算将
                            local needMemorySize = (self.totalSize + ADD_SPACE_SIZE) - MemorySize - DownloadedSize       
                            if needMemorySize > 0 then
                                isPop = true                   
                                UIModule.OpenDialog({ id = Constants.UITypeIds.PredownloadMemoryTipsPopup, parameters = { DownloadedSize = DownloadedSize , TotalSize = self.totalSize , needMemorySize = self.needMemorySize} })        
                            end  
                        end  
                    end                    
                end
            else 
                download.ProgressCallback = function(DownloadedSize, TotalSize, speed)
                    local size = DownloadedSize
                    local Progress = size / TotalSize
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Progressing, downloadSize = size, totalSize = TotalSize, progress = Progress, speed = speed })
                    local proInt = math.floor(Progress * 100)
                    local distance = 20
                    if proInt < 20 then
                        distance = 5
                        if proInt < 5 then
                            distance = 1
                        end
                    end
                    local multiple = math.floor(proInt / distance)
                    local uploadPoint = multiple * distance
                    if not progressMap[tostring(uploadPoint)] then
                        progressMap[tostring(uploadPoint)] = uploadPoint
                        xRecord.record('14-005', string.format('download_progress_small_%s%%', uploadPoint))
                    end
                end
            end
            local downloadMemberInfo = download:GetType()
            local property = downloadMemberInfo:GetProperty("OnCheckPercentCallback")
            if isNotNull(property) then
                local verifyProgress = 0
                download.OnCheckPercentCallback = function(percent)
                    local proInt = math.floor(percent)
                    if proInt >= verifyProgress then
                        local currentProgress = verifyProgress
                        while proInt >= verifyProgress do
                            currentProgress = verifyProgress
                            verifyProgress = verifyProgress + 20
                        end
                        xRecord.record('14-022', string.format('verify_progress_%s%%', currentProgress))
                    end
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.ResourceNewCheck, progress = percent })
                end
            end
            property = downloadMemberInfo:GetProperty("OnLastMd5CheckCallback")
            if isNotNull(property) then
                download.OnLastMd5CheckCallback = function()
                    xRecord.record('14-022', string.format('verify_progress_%s%%', 75))
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.ResourceCheck })
                end
            end
            property = downloadMemberInfo:GetProperty("OnLastMargeFileCallback")
            if isNotNull(property) then
                download.OnLastMargeFileCallback = function()
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.ResourceMarge })
                end
            end
            property = downloadMemberInfo:GetProperty("OnFailCallback")
            if isNotNull(property) then
                download.OnFailCallback = function(error)
                    if error == Constants.DownloadErrorType.INSUFFICIENT_DISK_SPACE_ERROR then
                        -- GameUtils.SecondConfirm(localize("空间不足,请清理空间") ,function ()
                        --     -- CS.UnityEngine.Application.Quit()
                        -- end,function ()
                        --     -- CS.UnityEngine.Application.Quit()
                        -- end)
                        -- GameUtils.Toast(localize("空间不足,请清理空间"), 5)
                        -- GameUtils.Toast(localize("空间不足"))
                    elseif error == Constants.DownloadErrorType.UNKNOWN then
                        if not IS_REVIEW then
                            GameUtils.Toast(localize("未知错误"))    
                        end
                    elseif error == Constants.DownloadErrorType.FILE_MERGE_ERROR then
                        if not IS_REVIEW then
                            GameUtils.Toast(localize("文件错误"))
                        end
                    elseif error == Constants.DownloadErrorType.FILE_CHECK_ERROR then
                        if not IS_REVIEW then
                            GameUtils.Toast(localize("文件检测错误"))    
                        end
                    elseif error == Constants.DownloadErrorType.NETWORK_ERROR then
                        if not IS_REVIEW then
                            GameUtils.Toast(localize("网络错误"))    
                        end
                    elseif error == Constants.DownloadErrorType.BLOCK_ERROR then
                        if not IS_REVIEW then
                            GameUtils.Toast(localize("下载错误，修正中"))    
                        end
                    end
                    xRecord.record('14-010', tostring(error))
                end
            end
            
            property = downloadMemberInfo:GetProperty("OnFailStringCallback")
            if isNotNull(property) then
                download.OnFailStringCallback = function(data)
                    local downloadInfo = table.deserialize(data)
                    if isNotNull(downloadInfo.value) then
                        local value = checkInt(downloadInfo.value)
                        if value == Constants.DownloadErrorType.INSUFFICIENT_DISK_SPACE_ERROR then
                            GameUtils.Toast(localize("空间不足,请清理空间"), 5)
                            Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.DownloadSpaceNotEnough, downloadInfo = downloadInfo})
                        end
                    end 
                end
            end

            download:SetFinishCallback(function(state)
                xRecord.record('14-006', 'download_progress_small_completed')
                ---@type Engine.Lib.Updater.DownloadState
                local mState = state
                if mState.IsError then
                    xRecord.record('14-010', checkString(mState.Error.Message))
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Error, error = tostring(mState.Error.Message) })
                else
                    ----正常的下载完成
                    if not download.IsFinished then
                        download:Finish()
                    end
                    download.ProgressCallback = nil
                    download:SetFinishCallback(nil)
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.DownloadDone, progress = 100 })
                end
                xRecord.af_internal("download_end" , {version = CS.UnityEngine.Application.version})
            end)
            local vendorPath = PathUtility.Combine(ResourceModule.AppDataPath, ResourceModule.ProductRelPath)
            local decompressState = DecompressState(vendorPath, download)
            local decomProgress = 0
            decompressState.OnDecompressProgressAction = function()
                local proInt = decompressState.Progress * 100
                if proInt >= decomProgress then
                    local currentProgress = decomProgress
                    while proInt >= decomProgress do
                        currentProgress = decomProgress
                        decomProgress = decomProgress + 20
                    end
                    xRecord.record('14-007', string.format('decom_progress_%s%%', currentProgress))
                end
                ---解压文件显示
                Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Decompressing, progress = decompressState.Progress })
            end
            if KTool.UNITY_IOS() then
                decompressState.IsDeleteZip = false
            else
                decompressState.IsDeleteZip = isDelete    
            end
            decompressState:SetFinishCallback(function()
                if decompressState.IsError then
                    xRecord.record('14-010', checkString(decompressState.Error.Message))
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Error, error = decompressState.Error.Message })
                    ----解压出错的情况下，清理下下载目录
                    local downloadPath = PathUtility.Combine(ResourceModule.AppDataPath, "Download")
                    if Exists(downloadPath) then
                        ---更新写入的路径
                        PathUtility.Clean(downloadPath)
                    end
                    if not Exists(downloadPath) then
                        Directory.CreateDirectory(downloadPath)
                    end
                else
                    xRecord.record('14-008', 'decom_finish')
                end
            end)

            local isUseMd5 = true
            if self.downloadBeforeInfo.xxh64 and not string.isEmpty(self.downloadBeforeInfo.xxh64) then
                isUseMd5 = false
            end
            local verifyPackageState = VerifyPackageState(download, isUseMd5)
            ---@type Engine.Lib.Updater.Updater
            local updater = Updater({ download, verifyPackageState, decompressState })
            updater.FinishCallback = function(update)
                ---更新完成进入游戏
                if updater.IsError then
                    xRecord.record('14-010', tostring(updater.Error.Message))
                    ---更新出现错误了
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Error, error = updater.Error.Message })
                else
                    ---设置记录
                    PlayerPrefsUtility.SetEncryptedString(SmallPackageDownloaded, CS.UnityEngine.Application.version)
                    PlayerPrefsUtility.SetEncryptedString("IS_NEW_SMALL_PACKAGE", "1")
                    PlayerPrefsUtility.Save() --修正分包下载在pc上的有些模拟器，前一个包安装完再立即覆盖新的包，然后写入的preVersion信息为旧的情况
                    local downloadPath = PathUtility.Combine(ResourceModule.AppDataPath, "Download")
                    if Exists(downloadPath) then
                        ---更新写入的路径
                        PathUtility.Clean(downloadPath)
                    end
                    if not Exists(downloadPath) then
                        Directory.CreateDirectory(downloadPath)
                    end
                    Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.Finish })
                end
            end
            xRecord.af_internal("download_start" , {version = CS.UnityEngine.Application.version})
            ---开启线程来检测状态
            CS.Engine.Lib.AppEngine._Instance:StartCoroutine(updater:StartEnumerator())
            while not updater.IsDone do
                cs_coroutine.yield_return(Yielders.EndOfFrame)
            end
            download:RemoveListeners()
        end)
    end)
end

function GameStartInit:GetUpdatePatches()
    local json = checkTable(self.userUpdateInfo)
    local remoteV = AppVersion(json.version)
    local localV = Game.Instance.Version
    local patches = {}
    local subPatches = {}
    if json.patches and table.count(json.patches) > 0 then
        local t = {}
        for key, v in pairs(json.patches) do
            ---@type Engine.Lib.Updater.PatchDojo
            local patchDojo = CS.Engine.Lib.Updater.PatchDojo()
            patchDojo.md5 = v.md5
            patchDojo.size = v.size
            patchDojo.url = string.format('%s/%s/%s.zip',json.updateUrl, json.version, key)
            patchDojo.ZipName = string.format("%s.zip", json.version)
            t[key] = patchDojo
        end
        patches = t
    end
    if json.subPatches and table.count(json.subPatches) > 0 then
        local t = {}
        for key, v in pairs(json.subPatches) do
            ---@type Engine.Lib.Updater.PatchDojo
            local patchDojo = CS.Engine.Lib.Updater.PatchDojo()
            patchDojo.md5 = v.md5
            patchDojo.size = v.size
            patchDojo.url = string.format('%s/%s/%s.zip',json.updateUrl, json.version, key)
            patchDojo.ZipName = string.format("%s.zip", json.version)
            t[key] = patchDojo
        end
        subPatches = t
    end
    local targetPatches = {}
    if string.isEmpty(json.subVersion) then
        targetPatches = patches
    else
        targetPatches = subPatches
    end
    return localV:CompareTo(remoteV) < 0 and targetPatches[localV:ToStandardVersionString()], targetPatches[localV:ToStandardVersionString()]
end

