---DecompressState
---解压事件
---@param localUpdatePath string
---@param downloadState Engine.Lib.Updater.DownloadState
function GameStartInit:DecompressState(localUpdatePath, downloadState)
    local decompressState = DecompressState(localUpdatePath, downloadState)
    decompressState.OnDecompressProgressAction = function()
        ---解压文件显示
        --self.TitleText.text = tostring(path)
        self.Slider.value = checkNumber(decompressState.Progress)
        self.ProText.text = string.format('%d%%', math.floor(decompressState.Progress * 100))
    end
    decompressState:SetFinishCallback(function()
        xRecord.record('14-008', 'decom_finish')
        if decompressState.IsError then
            ----解压出错的情况下，清理下下载目录
            local downloadPath = PathUtility.Combine(ResourceModule.AppDataPath, "Download")
            if Exists(downloadPath) then
                ---更新写入的路径
                PathUtility.Clean(downloadPath)
            end
            if not Exists(downloadPath) then
                Directory.CreateDirectory(downloadPath)
            end
        end
    end)
    return decompressState
end

---CompareVersionState
---版本比对的逻辑状态
---@param localUpdatePath string
---@param versionFileName string
function GameStartInit:CompareVersionState(localUpdatePath, versionFileName)
    --检测版本
    ---@type Engine.Lib.Updater.CompareVersionState
    local checkV = CompareVersionState(self.requestVersionState_, localUpdatePath, versionFileName)
    ---自定义检测版本的处理逻辑
    checkV.OnCompareBeforeAction = function(state)
        ---@type Engine.Lib.Updater.UpdateDojo
        local updateDojo = checkV.VersionState.RemoteResVersion
        ---1、处理是否是强制更新
        ---2、先处理是否是停机维护
        ---3、处理是否是审核服
        ---4、处理更新
        ---5、结束后finish
        if updateDojo.isForceUpdate == 1 then
            xTry(function()
                ---@type Engine.Modules.AbstractResourceLoader
                local loader = ResourceModule.LoadBundleSync("Prefabs/Common/SecondConfirmPopUp.prefab", nil, true)
                if loader.IsSuccess then
                    local parent = UIModule.RootCanvas.transform.parent
                    --//将检测更新界面加入到初始页面中去
                    local go = loader:Instantiate(parent.transform, false)
                    loader:Release()
                    go.name = "SecondConfirmPopUp"
                    if not KTool.IsNull(go) and not KTool.IsNull(parent) then
                        local t = go:GetComponent(typeof(RectTransform))
                        t.anchorMin = Vector2.zero
                        t.anchorMax = Vector2.one
                        t.offsetMin = Vector2.zero
                        t.offsetMax = Vector2.zero
                        t.localPosition = Vector3.zero
                        t.localRotation = Quaternion.identity
                        t.localScale = Vector3.one
                        go.layer = parent.gameObject.layer
                        ---获取lua脚本然后执行方法
                        local uiSecondConfirm = GetLuaBehaviour(go, "Game.Behaviours.UISecondConfirm")
                        if not KTool.IsNull(uiSecondConfirm) then
                            uiSecondConfirm.Env:ShowHUD(localize('您的当前版本过低，请前往下载最新版本'), '', function()
                                CfUtils.OpenURL(updateDojo.forceUpdateUrl)
                                xRecord.record('14-002', string.format('click_y_%s_2', updateDojo.version))
                            end, function()
                                xRecord.record('14-003', string.format('click_n_%s_2', updateDojo.version))
                                CS.UnityEngine.Application.Quit()
                            end)
                        end
                    end
                else
                    loader:Release(true)
                end
            end, function()
                ---如果因各种更新异常直接跳转
                CfUtils.OpenURL(updateDojo.forceUpdateUrl)
            end)
        elseif updateDojo.isMaintain == 1 then
            ---弹出停机维护的提示的处理
        elseif updateDojo.isReview > 0 then
            ---审核服务器,更改服务器
            HttpModule.ServerHost = checkString(updateDojo.reviewUrl)
            HttpModule.Instance:ParseDomain()
            local staticType = typeof(HttpModule)
            local BindingFlags = CS.System.Reflection.BindingFlags
            local propertyInfo = isNotNull(staticType:GetProperty("IsEnableHost", BindingFlags.Static | BindingFlags.Public)) 
            if propertyInfo then
                HttpModule.IsEnableHost = false    
            end
            IS_REVIEW = true
            IS_REVIEW_INT = checkNumber(updateDojo.isReview)
            if not checkV.IsFinished then
                checkV:Finish() ---直接进入下一状态
            end
        else
            ---正常的版本审核的逻辑处理
            if not checkV.IsFinished then
                checkV:Finish() ---直接进入下一状态
            end
        end
    end
    return checkV
end

---DownloadState
---下载状态
---@param compareVersionState Engine.Lib.Updater.CompareVersionState
---@param packagePrefix string
function GameStartInit:DownloadState(compareVersionState, packagePrefix)
    ---@type Engine.Lib.Updater.DownloadState
    local download = DownloadState(compareVersionState, ResourceModule.AppDataPath, packagePrefix)
    download.IsAutoState = false ---非自动状态有一处提示
    download.UseRetry = false ---使用重试机制
    local startProgress = 0
    download.ProgressCallback = function(DownloadedSize, TotalSize, speed)
        local Progress = DownloadedSize / TotalSize
        if not isNull(self.TitleText) then
            self.TitleText.text = localize('下载资源中...(_pro/_total) (_speed/s)', { _pro = Utils.HumanReadableBytes(checkNumber(DownloadedSize), false),
                                                                                      _total = Utils.HumanReadableBytes(checkNumber(TotalSize), false), _speed = Utils.HumanReadableBytes(checkNumber(speed)) })
            self.Slider.value = checkNumber(Progress)
            self.ProText.text = string.format('%.2f%%', math.min(Progress * 100, 100))
            local proInt = Progress * 100
            if proInt >= startProgress then
                local currentProgress = startProgress
                while proInt >= startProgress do
                    currentProgress = startProgress
                    startProgress = startProgress + 20
                end
                xRecord.record('14-005', string.format('download_progress_%s%%',currentProgress))
            end
        end
    end
    if download.UseRetry then
        download.OnRetryAction = function()
            if download.IsError then
                if iskindof(download.Error, typeof(CS.System.TimeoutException)) then
                    ---如果是超时状态，重试的逻辑
                    if download.RetryTimes > 3 then
                        self.TitleText.text = download.Error.Message
                        if not download.IsFinished then
                            download:Finish()
                        end
                    else
                        ---TODO 重试的逻辑可行
                        --CS.Engine.Lib.CoWait.Start():Coroutine(util.cs_generator(function()
                        --    coroutine.yield(Yielders.GetWaitForSeconds(5))
                        --    download:StartDownload()
                        --    download.RetryTimes = download.RetryTimes + 1
                        --end))
                    end
                end
            else
                ----正常的下载完成
                download.UseRetry = false
                if not download.IsFinished then
                    download:Finish()
                end
                ---强制结束,料子炸开下
                if not isNull(self.ActiveNode) then
                    KTool.SetActive(self.ActiveNode.gameObject, true)
                end
                self.TitleText.text = localize('资源下载完成，开始解压...')
                self.ProText.text = string.format('%d%%', 100)
            end
        end
    end
    download:SetFinishCallback(function(state)
        self.hasUpdateZip = true
        xRecord.record('14-006', 'download_completed')
        ---@type Engine.Lib.Updater.DownloadState
        local mState = state
        if mState.IsError then
            ---直接显示错误
            self.TitleText.text = mState.Error.Message
        else
            ----正常的下载完成
            download.UseRetry = false
            if not download.IsFinished then
                download:Finish()
            else
                download.ProgressCallback = nil
                download:SetFinishCallback(nil)
            end
            ---强制结束
            self.TitleText.text = localize('资源下载完成，开始解压...')

            self.ProText.text = string.format('%d%%', 100)
        end
    end)
    local downloadMemberInfo = download:GetType()
    local property = downloadMemberInfo:GetProperty("OnCheckPercentCallback")
    if isNotNull(property) then
        local verifyProgress = 0
        download.OnCheckPercentCallback = function(percent)
            local proInt = math.floor(percent)
            if proInt >= verifyProgress then
                local currentProgress = verifyProgress
                while proInt >= verifyProgress do
                    currentProgress = verifyProgress
                    verifyProgress = verifyProgress + 20
                end
                self.TitleText.text = localize("文件校验中...")
                self.ProText.text = string.format('%d%%', verifyProgress)
                xRecord.record('14-022', string.format('verify_progress_%s%%', currentProgress))
            end
        end
    end
    property = downloadMemberInfo:GetProperty("OnLastMd5CheckCallback")
    if isNotNull(property) then
        download.OnLastMd5CheckCallback = function()
            xRecord.record('14-022', string.format('verify_progress_%s%%', 75))
            self.TitleText.text = localize("文件合并中，请耐心等待...")
            self.ProText.text = string.format('%d%%', 75)
            -- Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.ResourceCheck })
        end
    end
    property = downloadMemberInfo:GetProperty("OnLastMargeFileCallback")
    if isNotNull(property) then
        download.OnLastMargeFileCallback = function()
            self.TitleText.text = localize("文件合并中，请耐心等待...")
            -- Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.ResourceMarge })
        end
    end
    property = downloadMemberInfo:GetProperty("OnFailCallback")
    if isNotNull(property) then
        download.OnFailCallback = function(error)
            if error == Constants.DownloadErrorType.INSUFFICIENT_DISK_SPACE_ERROR then
                GameUtils.Toast(localize("空间不足,请清理空间"), 5)
            elseif error == Constants.DownloadErrorType.UNKNOWN then
                GameUtils.Toast(localize("未知错误"))
            elseif error == Constants.DownloadErrorType.FILE_MERGE_ERROR then
                GameUtils.Toast(localize("文件错误"))
            elseif error == Constants.DownloadErrorType.FILE_CHECK_ERROR then
                GameUtils.Toast(localize("文件检测错误"))
            elseif error == Constants.DownloadErrorType.NETWORK_ERROR then
                GameUtils.Toast(localize("网络错误"))
            elseif error == Constants.DownloadErrorType.BLOCK_ERROR then
                GameUtils.Toast(localize("下载错误，修正中"))
            end
        end
    end
    return download
end

---StartCoroutine
---@param updater Engine.Lib.Updater.Updater
function GameStartInit:StartCoroutine(updater)
    AppEngine._Instance:StartCoroutine(updater:StartEnumerator())
    while not updater.IsDone do
        cs_coroutine.yield_return(Yielders.EndOfFrame)
    end
end

---__CheckUpdateLogical
---开始检测更新的实际的逻辑处理
