function GameStartInit:CheckThirdAndUpdatePackage(paramter)
    paramter = paramter  or {}
    local preVersion = PlayerPrefsUtility.GetEncryptedString(SmallPackageDownloaded, "")
    if string.isEmpty(preVersion) then
        preVersion = CS.UnityEngine.Application.version
    end
    local thirdVersion = PlayerPrefsUtility.GetEncryptedString(ThirdPackageDownloaded, "")
    if not string.isEmpty(thirdVersion) then
        preVersion = preVersion .. ";" .. thirdVersion
    end
    GameUtils.Request("User/downloadBefore", { preVersion = preVersion }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            self.downloadBeforeInfo = checkTable(response.data)
            if paramter.func and paramter.cancelFunc then
                ---@type Engine.UI.UIRaycastBlocker
                local blockerInstance = CS.Engine.UI.UIRaycastBlocker.Instance
                local thirdPackageConfig = ThirdDownloadManager:GetDownloadThirdPackage(self.downloadBeforeInfo)
                GameUtils.SecondConfirm(localize("要下载_num_增量包才可以进入游戏" ,{_num_ = Utils.HumanReadableBytes(thirdPackageConfig.totalZipSize)} ) , function ()
                    blockerInstance:AddCondition("START_GAME_BUTTON")
                    ThirdDownloadManager:SetSupportThirdPackages(self.downloadBeforeInfo)
                    KTool.SetActive(self.UpdateBottom , true) 
                    self:StartDownloadThirdPackage(thirdPackageConfig , paramter)
                end , paramter.cancelFunc)
            else 
                ThirdDownloadManager:SetSupportThirdPackages(self.downloadBeforeInfo)
                local thirdPackageConfig = ThirdDownloadManager:GetDownloadThirdPackage(self.downloadBeforeInfo)
                KTool.SetActive(self.UpdateBottom , true) 
                self:StartDownloadThirdPackage(thirdPackageConfig , paramter)
            end
         
        end
    end)
end

function GameStartInit:StartDownloadThirdPackage(thirdPackageConfig , paramter)
    paramter = paramter or {}
    cs_coroutine.start(function()
        xTry(function()
            ---@type Engine.Lib.Updater.DownloadState
            local download = DownloadState(nil, ResourceModule.AppDataPath, "Download")
            download.PatchMd5S = thirdPackageConfig.patchDojos
            download.OnLastMd5CheckCallback = function()
                -- xRecord.record('14-022', string.format('verify_progress_%s%%', 75))
                self.TitleText.text = localize("文件合并中，请耐心等待...")
                self.ProText.text = string.format('%d%%', 75)
                xRecord.record('20-005', 'verify_third_start')
            end
            KTool.SetActive(self.Slider.gameObject, true)
            download.OnLastMargeFileCallback = function()
                self.TitleText.text = localize("文件合并中，请耐心等待...")
                xRecord.record('20-002', 'download_third_completed')
            end
            local verifyProgress = 0
            local startProgress = 0
            xRecord.record('20-001', string.format('downloading_third_%s',CS.UnityEngine.Application.version))
            download.ProgressCallback = function(DownloadedSize, TotalSize, speed)
                local Progress = DownloadedSize / TotalSize
                if not isNull(self.TitleText) then
                    self.TitleText.text = localize('下载资源中...(_pro/_total) (_speed/s)', { _pro = Utils.HumanReadableBytes(checkNumber(DownloadedSize), false),
                                                                                              _total = Utils.HumanReadableBytes(checkNumber(TotalSize), false), _speed = Utils.HumanReadableBytes(checkNumber(speed)) })
                    self.Slider.value = checkNumber(Progress)
                    self.ProText.text = string.format('%.2f%%', math.min(Progress * 100, 100))
                    local proInt = Progress * 100
                    if proInt >= startProgress then
                        local currentProgress = startProgress
                        while proInt >= startProgress do
                            currentProgress = startProgress
                            startProgress = startProgress + 20
                        end
                        -- xRecord.record('14-005', string.format('download_progress_%s%%',currentProgress))
                    end
                end
            end
            download.OnCheckPercentCallback = function(percent)
                local proInt = math.floor(percent)
                if proInt >= verifyProgress then
                    local currentProgress = verifyProgress
                    while proInt >= verifyProgress do
                        currentProgress = verifyProgress
                        verifyProgress = verifyProgress + 20
                    end
                    self.TitleText.text = localize("文件校验中...")
                    self.ProText.text = string.format('%d%%', verifyProgress)
                    -- xRecord.record('14-022', string.format('verify_progress_%s%%', currentProgress))
                end
            end
            if download.UseRetry then
                download.OnRetryAction = function()
                    if download.IsError then
                        if iskindof(download.Error, typeof(CS.System.TimeoutException)) then
                            ---如果是超时状态，重试的逻辑
                            if download.RetryTimes > 3 then
                                self.TitleText.text = download.Error.Message
                                if not download.IsFinished then
                                    download:Finish()
                                end
                            else
                                ---TODO 重试的逻辑可行
                                --CS.Engine.Lib.CoWait.Start():Coroutine(util.cs_generator(function()
                                --    coroutine.yield(Yielders.GetWaitForSeconds(5))
                                --    download:StartDownload()
                                --    download.RetryTimes = download.RetryTimes + 1
                                --end))
                            end
                        end
                    else
                        ----正常的下载完成
                        download.UseRetry = false
                        if not download.IsFinished then
                            download:Finish()
                        end
                        ---强制结束,料子炸开下
                        if not isNull(self.ActiveNode) then
                            KTool.SetActive(self.ActiveNode.gameObject, true)
                        end
                        self.TitleText.text = localize('资源下载完成，开始解压...')
                        self.ProText.text = string.format('%d%%', 100)
                    end
                end
            end
            download.OnFailCallback = function(error)
                if error == Constants.DownloadErrorType.INSUFFICIENT_DISK_SPACE_ERROR then
                    -- GameUtils.SecondConfirm(localize("空间不足,请清理空间") ,function ()
                    --     -- CS.UnityEngine.Application.Quit()
                    -- end,function ()
                    --     -- CS.UnityEngine.Application.Quit()
                    -- end)
                    -- GameUtils.Toast(localize("空间不足,请清理空间"), 5)
                    -- GameUtils.Toast(localize("空间不足"))
                elseif error == Constants.DownloadErrorType.UNKNOWN then
                    if not IS_REVIEW then
                        GameUtils.Toast(localize("未知错误"))    
                    end
                elseif error == Constants.DownloadErrorType.FILE_MERGE_ERROR then
                    if not IS_REVIEW then
                        GameUtils.Toast(localize("文件错误"))
                    end
                elseif error == Constants.DownloadErrorType.FILE_CHECK_ERROR then
                    if not IS_REVIEW then
                        GameUtils.Toast(localize("文件检测错误"))    
                    end
                elseif error == Constants.DownloadErrorType.NETWORK_ERROR then
                    if not IS_REVIEW then
                        GameUtils.Toast(localize("网络错误"))    
                    end
                elseif error == Constants.DownloadErrorType.BLOCK_ERROR then
                    if not IS_REVIEW then
                        GameUtils.Toast(localize("下载错误，修正中"))    
                    end
                end
                xRecord.record('14-010', tostring(error))
            end
            download.OnFailStringCallback = function(data)
                local downloadInfo = table.deserialize(data)
                if isNotNull(downloadInfo.value) then
                    local value = checkInt(downloadInfo.value)
                    if value == Constants.DownloadErrorType.INSUFFICIENT_DISK_SPACE_ERROR then
                        GameUtils.Toast(localize("空间不足,请清理空间"), 5)
                        Events.Broadcast("DownloadStatus", { status = PreDownloadConstants.DownloadStatus.DownloadSpaceNotEnough, downloadInfo = downloadInfo})
                    end
                end 
            end
            download:SetFinishCallback(function(state)
                ---@type Engine.Lib.Updater.DownloadState
                local mState = state
                if mState.IsError then
                
                else
                    ----正常的下载完成
                    if not download.IsFinished then
                        download:Finish()
                    end
                    download.ProgressCallback = nil
                    download:SetFinishCallback(nil)
                    
                    xRecord.record('20-005', 'verify_third_completed')
                    xRecord.record('20-003', 'decom_third_start')
                end
            end)
            local vendorPath = PathUtility.Combine(ResourceModule.AppDataPath, ResourceModule.ProductRelPath)
            local decompressState = DecompressState(vendorPath, download)
            local decomProgress = 0
            decompressState.OnDecompressProgressAction = function()
                local proInt = decompressState.Progress * 100
                if proInt >= decomProgress then
                    local currentProgress = decomProgress
                    while proInt >= decomProgress do
                        currentProgress = decomProgress
                        decomProgress = decomProgress + 20
                    end
                end
                self.TitleText.text = localize("资源解压中")
                self.Slider.value = checkNumber(decompressState.Progress)
                self.ProText.text = string.format('%d%%', math.floor(decompressState.Progress * 100))
            end
            decompressState.IsDeleteZip = false
            decompressState:SetFinishCallback(function()
                if decompressState.IsError then
                    ----解压出错的情况下，清理下下载目录
                    local downloadPath = PathUtility.Combine(ResourceModule.AppDataPath, "Download")
                    if Exists(downloadPath) then
                        ---更新写入的路径
                        PathUtility.Clean(downloadPath)
                    end
                    if not Exists(downloadPath) then
                        Directory.CreateDirectory(downloadPath)
                    end
                else
                    xRecord.record('20-004', 'decom_third_completed')
                end
            end)
            local verifyPackageState = VerifyPackageState(download, false)
            local updater = Updater({ download, verifyPackageState, decompressState })
            updater.FinishCallback = function(update)
                ---更新完成进入游戏
                if updater.IsError then
                    xRecord.record('14-010', tostring(updater.Error.Message))
                else
                    ThirdDownloadManager:StartDownloadThirdPackageVersion(ThirdPackageDownloaded , CS.UnityEngine.Application.version)
                    local downloadPath = PathUtility.Combine(ResourceModule.AppDataPath, "Download")
                    if Exists(downloadPath) then
                        ---更新写入的路径
                        PathUtility.Clean(downloadPath)
                    end
                    if not Exists(downloadPath) then
                        Directory.CreateDirectory(downloadPath)
                    end
                end
            end
            CS.Engine.Lib.AppEngine._Instance:StartCoroutine(updater:StartEnumerator())
            while not updater.IsDone do
                cs_coroutine.yield_return(Yielders.EndOfFrame)
            end
            download:RemoveListeners()
            if paramter.func then
                KTool.SetActive(self.UpdateBottom , false) 
                paramter.func()
            else 
                -- 重新掉用更新接口
                self:CheckUpdate()
            end
            
        end)
    end)
end
function GameStartInit:CheckUpdater()
    -----@type Engine.Lib.Updater.WWWEx
    local wwwEx = self.requestVersionState_:MakeWWWEx(5, 10)
    self.TitleText.text = localize('开始检测更新...')
    KTool.SetActive(self.BtnUpdate, false)
    local isSuccess = false
    cs_coroutine.yield_return(wwwEx:LoadAsync(function(www)
        local wEx = wwwEx:Decrypt(www)
        local data = table.deserialize((wEx.data))
        --local json = {appVersion="3.0.2",version="3.0.2.12021454",subVersion="",title="停服了",updateContent="",isReview=0,reviewUrl="",isMaintain=1,isForceUpdate=0,forceUpdateUrl="",updateUrl="https://eater-ios-update.fantanggame.com/cat_rc4/ios/patches",backupUrl="h/patches",subPatches={},needRestart=0}
        local json = checkTable(data.data)
        if checkNumber(data.errCode) == 0 then
            ---@type Engine.Lib.Updater.UpdateDojo
            local dojo = CS.Engine.Lib.Updater.UpdateDojo()
            dojo.appVersion = json.appVersion
            dojo.version = json.version
            dojo.subVersion = json.subVersion
            dojo.title = json.title
            dojo.content = json.content
            dojo.reviewUrl = tostring(json.reviewUrl)
            dojo.isMaintain = checkNumber(json.isMaintain)
            KCookie.Set("IS_MAINTAIN_SERVER", checkString(json.isMaintain))
            dojo.isForceUpdate = checkNumber(json.isForceUpdate)
            dojo.isReview = checkNumber(json.isReview)
            dojo.forceUpdateUrl = tostring(json.forceUpdateUrl)
            dojo.updateUrl = tostring(json.updateUrl)
            dojo.backupUrl = tostring(json.backupUrl)
            dojo.backupUrl2 = tostring(json.backupUrl2)
            dojo.needRestart = checkNumber(json.needRestart)
            dojo.multithreading = 1
            if isSet(json, "multithreading") then
                dojo.multithreading = checkNumber(json.multithreading)
            end
            ---patches数据
            if json.patches and table.count(json.patches) > 0 then
                local t = {}
                for key, v in pairs(json.patches) do
                    ---@type Engine.Lib.Updater.PatchDojo
                    local patchDojo = CS.Engine.Lib.Updater.PatchDojo()
                    patchDojo.md5 = v.md5
                    patchDojo.size = v.size
                    t[key] = patchDojo
                end
                dojo.patches = t
            end
            if json.subPatches and table.count(json.subPatches) > 0 then
                local t = {}
                for key, v in pairs(json.subPatches) do
                    ---@type Engine.Lib.Updater.PatchDojo
                    local patchDojo = CS.Engine.Lib.Updater.PatchDojo()
                    patchDojo.md5 = v.md5
                    patchDojo.size = v.size
                    t[key] = patchDojo
                end
                dojo.subPatches = t
            end
            self.requestVersionState_.RemoteResVersion = dojo
            if checkNumber(json.isForceUpdate) == 1 then
                xRecord.record('14-001', string.format('new_version_%s_2', tostring(dojo.version)))
            else
                xRecord.record('14-001', string.format('new_version_%s_1', tostring(dojo.version)))
            end
            self.RemoteVersionTxt.text = self.requestVersionState_.RemoteResVersion.version
            isSuccess = true
            if self.requestVersionState_.RemoteResVersion.isMaintain == 1 then
                self.TitleText.text = ""
                UIModule.OpenDialog({ id = LoginStopService, parameters = { title = dojo.title, content = dojo.content, closeCB = function()
                    KTool.SetActive(self.BtnUpdate, true)
                end } })
            end
        else
            self.TitleText.text = tostring(data.errMsg)
        end
    end, function(www)
        printInfo(www.error)
        ---是否提示文件异常
        self.TitleText.text = tostring(www.error)
    end, function(www)
        ---timeout
        self.TitleText.text = localize('超时处理')
    end))

    while not isSuccess do
        cs_coroutine.yield_return()
    end

    if self.requestVersionState_.RemoteResVersion.isMaintain ~= 1 then
        self:PrepareUpdater()
    end
end

function GameStartInit:PrepareUpdater()
    local vendorPath = PathUtility.Combine(ResourceModule.AppDataPath, ResourceModule.ProductRelPath)
    ---版本比对的逻辑状态
    local compareVersionState = self:CompareVersionState(vendorPath, resource_version_filename)
    local downloadState = self:DownloadState(compareVersionState, "Download")
    local verifyPackageState = self:VerifyPackageState(downloadState)
    local decompressState = self:DecompressState(vendorPath, downloadState)
    UpdaterState.CustomOnError = function(s)
        xRecord.record('14-009', tostring(s))
        self.TitleText.text = s
    end
    cs_coroutine.yield_return(self:StartUpdater({ self.idleState_,
                                                  self.majorState_,
                                                  compareVersionState,
                                                  downloadState,
                                                  verifyPackageState,
                                                  decompressState, }))
end

---StartUpdater
---开启检测更新器
---@param states table 所有的状态列表
---@param requestVersionState Engine.Lib.Updater.RequestVersionState 请求状态
function GameStartInit:StartUpdater(states)
    ---@type Engine.Lib.Updater.Updater
    local updater = Updater(states)
    local function OnTransitionEvent(curState, nextS)
        printInfo(nextS)
        if iskindof(curState, typeof(CompareVersionState)) and
                iskindof(nextS, typeof(DownloadState)) then
            ---提示有更新弹出ui，然后再切到下一步下载状态的逻辑
            ---@type Engine.Lib.Updater.CompareVersionState
            --local curState
            if curState.LocalVersion:CompareTo(curState.RemoteVersion) < 0 then
                ----存在更新
                self.isUpdating = true ---存在更新
                ---本地小于远程
                KTool.SetActive(self.Slider.gameObject, true)
                KTool.SetActive(self.DownloadPromoteNode.gameObject, true)
                self.TitleText.text = ''
                local subTextTrans = self.DownloadPromoteNode.transform:Find("SubText")
                if subTextTrans then
                    local subText = subTextTrans:GetComponent(typeof(Text))
                    if not KTool.IsMobile() then
                        subText.text = ''
                    else
                        subText.text = localize('(建议在WIFI环境下下载)')
                    end
                end
                local contentTextTrans = self.DownloadPromoteNode:Find("Layout/Text")
                if not isNull(contentTextTrans) then
                    local localVersion = curState.LocalVersion:ToStandardVersionString()
                    local contentText = contentTextTrans:GetComponent(typeof(Text))
                    ---@type Engine.Lib.Updater.PatchDojo
                    local patchDojo = curState.TargetPatches:get_Item(localVersion)
                    if isNull(patchDojo) then
                        contentText.text = localize("远程不存在当前版本的信息[_version_]", { _version_ = localVersion })
                    else
                        local fileName = KTool.MD5_Str(string.format("%s%d", patchDojo.md5, 4))
                        local fileSystemName = string.format("Download/%s", fileName)
                        local tempPath = PathUtility.Combine(Application.persistentDataPath, fileSystemName)
                        local size = 0
                        if File.Exists(tempPath) then
                            xTry(function()
                                local all_lines = {}
                                for line in io.lines(tempPath) do
                                    all_lines[#all_lines + 1] = string.gsub(string.trim(line), '\r\n', '')
                                end
                                local parts = tonumber(all_lines[1])
                                for i = 1, parts do
                                    size = size + tonumber(all_lines[i * 3])
                                end
                                size = checkNumber(patchDojo.size) - tonumber(size)
                            end)
                        end
                        if size <= 0 then
                            size = checkNumber(patchDojo.size)
                        end
                        contentText.text = localize('检测到存在_size_更新是否下载？', { _size_ = Utils.HumanReadableBytes(size, false) })
                    end
                end
            else
                KTool.SetActive(self.UpdateBottom.gameObject, false)
            end
        end
    end
    UIEventProxy.Create(self.CommonButton_Main_OK.gameObject).onPointerClick = function(eventData)
        ---确认下载的逻辑
        local version = self.requestVersionState_.RemoteResVersion.version
        xRecord.record('14-002', string.format('click_y_%s_1', tostring(version)))
        KTool.SetActive(self.DownloadPromoteNode.gameObject, false)
        self.TitleText.text = localize('下载资源中...')
        ---@type Engine.Lib.Updater.DownloadState
        local currentState = updater.CurrentState
        currentState.IsAutoState = true ---开始下载资源的执行
    end

    updater:OnTransitionEvent("+", OnTransitionEvent)
    updater.FinishCallback = function(update)
        ---更新完成进入游戏
        updater:OnTransitionEvent("-", OnTransitionEvent)
        if updater.IsError then
            ---更新出现错误了
            print(updater.Error.Message)
        else
            if (not self.isSubPatch) and self.requestVersionState_:IsSubPatches() then
                if isNotNull(updater)  then
                    for k, v in pairs(states) do
                        if isNotNull(v) and  v:GetType().Name == "DownloadState" then
                            v:RemoveListeners()
                        end
                    end
                end
                ---还存在一个版本zip需要下载
                self.isSubPatch = true ---只会存在两个更新包，所以一次后标识更改
                local vendorPath = PathUtility.Combine(ResourceModule.AppDataPath, ResourceModule.ProductRelPath)
                local compareVersionState = self:CompareVersionState(vendorPath, resource_version_filename)
                local downloadState = self:DownloadState(compareVersionState, "Download")
                local verifyPackageState = self:VerifyPackageState(downloadState)
                local decompressState = self:DecompressState(vendorPath, downloadState)
                cs_coroutine.start(function()
                    self:StartUpdater({
                        compareVersionState,
                        downloadState,
                        verifyPackageState,
                        decompressState,
                    }, nil, false) ---不再有子版本
                end)
                
            else
                self.isSubPatch = false
                ---已成功更新完成
                ---更新成功了，需要重置下ab信息列表
                if self.hasUpdateZip then
                    ShowOverlay()
                    blocker:AddCondition("FIX_UPDATER_RES")
                    xTry(function()
                        cs_coroutine.start(function()
                            cs_coroutine.yield_return(UIModule.CloseDialogById(PassportDialog))
                            cs_coroutine.yield_return(UIModule.CloseDialogById(GameInitScene))
                            RestartVmReload(function()
                                self.hasUpdateZip = false
                                blocker:RemoveCondition("FIX_UPDATER_RES")
                                if isNotNull(updater)  then
                                    for k, v in pairs(states) do
                                        if isNotNull(v) and  v:GetType().Name == "DownloadState" then
                                            v:RemoveListeners()
                                        end
                                    end
                                end
                                cs_coroutine.yield_return(UIModule.OpenDialog({ id = GameInitScene }))
                            end)
                        end)
                    end, function()
                        blocker:RemoveCondition("FIX_UPDATER_RES")
                    end)
                else
                    if not self.isSmallPackage then
                        if isNotNull(updater)  then
                            for k, v in pairs(states) do
                                if isNotNull(v) and  v:GetType().Name == "DownloadState" then
                                    v:RemoveListeners()
                                end
                            end
                        end
                        UIModule.OpenDialog({ id = PassportDialog, parameters = { IS_NEW_SMALL_PACKAGE = true, backGame = self.isBackGame } })
                    end
                end
                self.isUpdating = false
                KTool.SetActive(self.UpdateBottom.gameObject, false)
            end

        end
    end
    ---开启线程来检测状态
    cs_coroutine.yield_return(self:StartCoroutine(updater))
end

---ShowRepairPromote
---生成修复提示
function GameStartInit:ShowRepairPromote()
    KTool.SetActive(self.RepairePromote.gameObject, true)
    local contentTextTrans = self.RepairePromote.transform:Find("Layout/Text")
    local OkBtn = self.RepairePromote.transform:Find("CommonOK/BtnOK")
