    end
    UIEventProxy.Create(CancelBtn.gameObject).onPointerClick = function(eventData)
        ---修复按钮确认
        KTool.SetActive(self.RepairePromote.gameObject, false)
    end
end

function GameStartInit:ReUpdateAction()
    KTool.SetActive(self.BtnNotice.gameObject, true)
    KTool.SetActive(self.BtnRepair.gameObject, true)
    local vendorPath = PathUtility.Combine(ResourceModule.AppDataPath, ResourceModule.ProductRelPath)
    self.isSmallPackage = IsSmallPackage()
    if self.isSmallPackage == true then
        CS.Engine.Lib.Updater.VerifyFileState.CleanAllUpdateFiles(vendorPath, nil)
        ---清理下载目录
        local downloadPath = PathUtility.Combine(ResourceModule.AppDataPath, "Download")
        if Exists(downloadPath) then
            ---更新写入的路径
            PathUtility.Clean(downloadPath)
        end
        if not Exists(downloadPath) then
            Directory.CreateDirectory(downloadPath)
        end
        ---重新加载一次版本号
        Game.Instance:LoadVersion(true)
        UIModule.OpenDialog({ id = PassportDialog, parameters = { IS_NEW_SMALL_PACKAGE = true, backGame = self.isBackGame } }) ---如果是新的分包的逻辑
    else
        ---更新写入的路径,直接走热更新的情况
        --PathUtility.Clean(vendorPath)
        self.isUpdating = true
        KTool.SetActive(self.UpdateBottom.gameObject, true)
        KTool.SetActive(self.Slider.gameObject, false)
        KTool.SetActive(self.DownloadPromoteNode.gameObject, false)
        self.TitleText.text = localize('清理资源中, 请稍后')
        local documentPath = ResourceModule.AppDataPath
        if KTool.IsMobile() then
            Directory.Delete(vendorPath, true)
            if not Exists(vendorPath) then
                Directory.CreateDirectory(vendorPath)
            end
            ---清理下载目录
            local downloadPath = PathUtility.Combine(documentPath, "Download")
            if Exists(downloadPath) then
                ---更新写入的路径
                PathUtility.Clean(downloadPath)
            end
            if not Exists(downloadPath) then
                Directory.CreateDirectory(downloadPath)
            end
            self.isUpdating = false
            ---重新加载一次版本号
            Game.Instance:LoadVersion(true)
            local function CreateGameWorld()
                Start()
                if isTable(ECSWorldMgr) then
                    ECSWorldMgr:GetInstance():Delete()
                end
                local ecsWorld = ECSWorldMgr:GetInstance():GetWorld(Constants.GameWorld)
                if not isNull(ecsWorld) then
                    ECSWorldMgr:GetInstance():DestroyWorld(ecsWorld)
                end
                ECSWorldMgr:GetInstance():Initial(200)
                ecsWorld = ECSWorldMgr:GetInstance():CreateWorld(Constants.GameWorld)
                ecsWorld:IsClient(true)
                ecsWorld:CreateEntity(Constants.PlayerEntityId, Constants.PlayerEntityId)
            end
            CreateGameWorld()
            self:CheckUpdate()
        else
            CS.Engine.Lib.ThreadWorker.Create(function()
                Directory.Delete(vendorPath, true)
                if not Exists(vendorPath) then
                    Directory.CreateDirectory(vendorPath)
                end
                ---清理下载目录
                local downloadPath = PathUtility.Combine(documentPath, "Download")
                if Exists(downloadPath) then
                    ---更新写入的路径
                    PathUtility.Clean(downloadPath)
                end
                if not Exists(downloadPath) then
                    Directory.CreateDirectory(downloadPath)
                end
            end, function()
                self.isUpdating = false
                ---重新加载一次版本号
                Game.Instance:LoadVersion(true)
                local function CreateGameWorld()
                    Start()
                    if isTable(ECSWorldMgr) then
                        ECSWorldMgr:GetInstance():Delete()
                    end
                    local ecsWorld = ECSWorldMgr:GetInstance():GetWorld(Constants.GameWorld)
                    if not isNull(ecsWorld) then
                        ECSWorldMgr:GetInstance():DestroyWorld(ecsWorld)
                    end
                    ECSWorldMgr:GetInstance():Initial(200)
                    ecsWorld = ECSWorldMgr:GetInstance():CreateWorld(Constants.GameWorld)
                    ecsWorld:IsClient(true)
                    ecsWorld:CreateEntity(Constants.PlayerEntityId, Constants.PlayerEntityId)
                end
                CreateGameWorld()
                self:CheckUpdate()
            end)
        end
        --UIModule.OpenDialog({ id = PassportDialog, parameters = { IS_NEW_SMALL_PACKAGE = true } })
    end
end

function GameStartInit:HideEnterButtons()
    KTool.SetActive(self.BtnNotice.gameObject, false)
    KTool.SetActive(self.BtnRepair.gameObject, false)
end

function GameStartInit:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---获取视频组件
        local rawImage = self.controller.transform:Find("RawImage")
        if not isNull(rawImage) then
            ---@type CriWare.CriManaMovieControllerForUI
            local controllerForUI = KTool.GetOrAddComponent(rawImage.gameObject, typeof(CS.CriWare.CriManaMovieControllerForUI))
            if not isNull(controllerForUI) and not Config.DEBUG_QUICK_START then
                ---@type Engine.Lib.StringTable
                local tableFile = CS.Engine.Modules.SettingModule.GetStringGrid("Data/LoginMovie/Movies", false)
                if tableFile.DataRows > 0 then
                    local names  = {}
                    for k, v in pairs(tableFile.id2Row) do
                        ---@type Engine.Lib.StringTableRow
                        local row = v
                        local switch = checkInt(row:ParseCell("switch", "0"))
                        if switch == 1 then
                            names[#names+1] = k
                        end
                    end
                    if #names > 0 then
                        if #names == 1  then
                            controllerForUI.player:SetFile(nil, GetManaPath(string.format("Movie/%s.usm", names[1])))
                            controllerForUI:Play()
                        end
                        if #names > 1 then
                            local AppEngine = CS.Engine.Lib.AppEngine
                            local version = AppEngine.GetAppBundleVersion()
                            local channelId = checkInt(version.ChannelId) 
                            for index , name in pairs(names) do
                                if channelId == 6010 and channelId <= 6011 then
                                    if name == "loginloading_tongyong" then
                                        controllerForUI.player:SetFile(nil, GetManaPath(string.format("Movie/%s.usm", name)))
                                        controllerForUI:Play()
                                        break
                                    end
                                else
                                    if name ~= "loginloading_tongyong" then
                                        controllerForUI.player:SetFile(nil, GetManaPath(string.format("Movie/%s.usm", name)))
                                        controllerForUI:Play()
                                        break
                                    end 
                                end
                            end
                        end
                       
                    end
                end
            end
        end
        if self.isSmallPackage then
            ---最新的流程，直接使用先登录后更新的逻辑
            UIModule.OpenDialog({ id = PassportDialog, parameters = { IS_NEW_SMALL_PACKAGE = true, backGame = self.isBackGame } })
        else
            ---需要直接启动检测更新的逻辑的请求的逻辑
            local ThirdDownloadManager = ThirdDownloadManager:GetInstance()
            if ThirdDownloadManager:IsStartDownloadThirdPackage() and( not ThirdDownloadManager:IsNotDwonloadingEnd()) then
                self:CheckThirdAndUpdatePackage()
            else 
                self:CheckUpdate()    
            end
        end
        if not KTool.IsNull(self.ImgTips) then
            local AppEngine = CS.Engine.Lib.AppEngine
            local version = AppEngine.GetAppBundleVersion()
            local channelId = checkInt(version.ChannelId) 
            if channelId == 6008 then
                ---@type Engine.UI.ImageAlterable
                local ImageAlterable = self.ImgTips
                ImageAlterable:LoadSprite("UIAtlas/GameInit/login_imgtext_tips_mianyou.png")
                ImageAlterable.isNativeSize = true
                KTool.SetActive(self.LogoImg.gameObject  , false) 
            elseif channelId == 6009 or channelId == 6011 then 
                ---@type Engine.UI.ImageAlterable
                local ImageAlterable = self.ImgTips
                ImageAlterable:LoadSprite("UIAtlas/GameInit/login_imgtext_tips_feixing.png")
                ImageAlterable.isNativeSize = true
                KTool.SetActive(self.ImgTips.gameObject , true)
            elseif channelId == 5043 or 
                channelId == 5044 or 
                channelId == 5045 or 
                channelId == 5046 or 
                channelId == 5047 or 
                channelId == 6004 or 
                channelId == 6012 or 
                (channelId >= 5100 and channelId <= 5200) then
                KTool.SetActive(self.ImgTips.gameObject , true)
            end
                    
        end
        --if KCookie.Get("GAME_BACK_TO_LOGIN") then
        --    self.RemoteVersionTxt.text = version:ToStandardVersionString()
        --else
        --    ----判断是否存在分包的逻辑
        --    if KCookie.Get('START_CHECK_UPDATE') == 1 then
        --        KCookie.RemoveAllListener('START_CHECK_UPDATE')
        --        --self:CheckUserAgree()
        --    end
        --    ---需要直接启动检测更新的逻辑的请求的逻辑
        --    self:CheckUpdate()
        --end
    end))
    return coWait
end

