function GameStartInit:OnFinalize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self._update_handler_update then
            Events.RemoveListener("UPDATE_REPAIR_UPDATE_ACTION", self._update_handler_update)
        end
        if self._update_handler_hide then
            Events.RemoveListener("UPDATE_REPAIR_HIDE_ACTION", self._update_handler_hide)
        end
        if self.startCheckUpdateHandler then
            Events.RemoveListener("PreDownloadCheckInOnSuccess", self.startCheckUpdateHandler)
        end
        if self.startSmallPackageHandler then
            Events.RemoveListener("StartPackageDownload", self.startSmallPackageHandler)
        end
        if self.playerEnterGameHandler then
            Events.RemoveListener("PlayerDownloadThirdEvent", self.playerEnterGameHandler)
            self.playerEnterGameHandler = nil
        end
        self._update_handler_update = nil
        self._update_handler_hide = nil
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要

    end))
    return coWait
end

return GameStartInit